CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY,name VARCHAR(190) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password TEXT NOT NULL,remember_token TEXT,is_super_admin BOOLEAN NOT NULL DEFAULT FALSE,locale VARCHAR(5) NOT NULL DEFAULT 'ar',email_verified_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),deleted_at TIMESTAMP NULL);
CREATE INDEX IF NOT EXISTS users_super_admin_idx ON users(is_super_admin);
CREATE TABLE IF NOT EXISTS auth_tokens (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL DEFAULT 'spa',expires_at TIMESTAMP NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS auth_tokens_user_idx ON auth_tokens(user_id);
CREATE TABLE IF NOT EXISTS plans (id BIGSERIAL PRIMARY KEY,name VARCHAR(190) NOT NULL,slug VARCHAR(190) UNIQUE NOT NULL,price_monthly NUMERIC(10,2) NOT NULL DEFAULT 0,price_yearly NUMERIC(10,2) NOT NULL DEFAULT 0,limits JSONB NOT NULL DEFAULT '{}'::jsonb,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
INSERT INTO plans(name,slug,price_monthly,price_yearly,limits) VALUES('Free','free',0,0,'{"max_courses":10,"max_students":100,"storage_mb":1024}') ON CONFLICT(slug) DO NOTHING;
CREATE TABLE IF NOT EXISTS academies (id BIGSERIAL PRIMARY KEY,owner_id BIGINT NOT NULL REFERENCES users(id),plan_id BIGINT REFERENCES plans(id) ON DELETE SET NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(190) UNIQUE NOT NULL,description TEXT,template VARCHAR(100) NOT NULL DEFAULT 'personal-instructor',language VARCHAR(5) NOT NULL DEFAULT 'ar',currency VARCHAR(3) NOT NULL DEFAULT 'USD',status VARCHAR(30) NOT NULL DEFAULT 'draft',theme JSONB,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),deleted_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS academy_members (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role VARCHAR(40) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(academy_id,user_id,role));
CREATE INDEX IF NOT EXISTS academy_members_user_idx ON academy_members(user_id,academy_id);
CREATE TABLE IF NOT EXISTS academy_domains (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,domain VARCHAR(255) UNIQUE NOT NULL,verification_token VARCHAR(255) NOT NULL,verified_at TIMESTAMP NULL,is_primary BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS courses (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,instructor_id BIGINT REFERENCES users(id) ON DELETE SET NULL,title VARCHAR(190) NOT NULL,slug VARCHAR(220) NOT NULL,description TEXT,price NUMERIC(10,2) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'draft',created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),deleted_at TIMESTAMP NULL,UNIQUE(academy_id,slug));
CREATE INDEX IF NOT EXISTS courses_academy_status_idx ON courses(academy_id,status);
CREATE TABLE IF NOT EXISTS course_sections (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,course_id BIGINT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,title VARCHAR(190) NOT NULL,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS lessons (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,course_id BIGINT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,section_id BIGINT NOT NULL REFERENCES course_sections(id) ON DELETE CASCADE,title VARCHAR(190) NOT NULL,type VARCHAR(30) NOT NULL DEFAULT 'video',content TEXT,duration_seconds INT NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,is_free_preview BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enrollments (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,course_id BIGINT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,status VARCHAR(30) NOT NULL DEFAULT 'active',enrolled_at TIMESTAMP NOT NULL DEFAULT NOW(),created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(course_id,user_id));
CREATE TABLE IF NOT EXISTS lesson_progress (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,course_id BIGINT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,lesson_id BIGINT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,completed BOOLEAN NOT NULL DEFAULT FALSE,watched_seconds INT NOT NULL DEFAULT 0,last_position INT NOT NULL DEFAULT 0,completed_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS course_progress (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,course_id BIGINT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,completed_lessons INT NOT NULL DEFAULT 0,total_lessons INT NOT NULL DEFAULT 0,percentage NUMERIC(5,2) NOT NULL DEFAULT 0,completed_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(user_id,course_id));
CREATE TABLE IF NOT EXISTS videos (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,lesson_id BIGINT REFERENCES lessons(id) ON DELETE SET NULL,uploader_id BIGINT REFERENCES users(id) ON DELETE SET NULL,original_name VARCHAR(255) NOT NULL,source_path TEXT,hls_path TEXT,status VARCHAR(30) NOT NULL DEFAULT 'uploading',duration_seconds INT NOT NULL DEFAULT 0,size_bytes BIGINT NOT NULL DEFAULT 0,error TEXT,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS video_transcodes (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,video_id BIGINT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,height SMALLINT NOT NULL,bandwidth INT NOT NULL,playlist_path TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(video_id,height));
CREATE TABLE IF NOT EXISTS coupons (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,code VARCHAR(100) NOT NULL,type VARCHAR(20) NOT NULL,value NUMERIC(10,2) NOT NULL,starts_at TIMESTAMP NULL,ends_at TIMESTAMP NULL,usage_limit INT NULL,used_count INT NOT NULL DEFAULT 0,minimum_amount NUMERIC(10,2) NOT NULL DEFAULT 0,course_ids JSONB,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(academy_id,code));
CREATE TABLE IF NOT EXISTS orders (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id),coupon_id BIGINT REFERENCES coupons(id) ON DELETE SET NULL,subtotal NUMERIC(10,2) NOT NULL,discount NUMERIC(10,2) NOT NULL DEFAULT 0,amount NUMERIC(10,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',payment_method VARCHAR(50),transaction_id VARCHAR(190),paid_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS order_items (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,course_id BIGINT NOT NULL REFERENCES courses(id),title VARCHAR(190) NOT NULL,price NUMERIC(10,2) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,provider VARCHAR(50) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',amount NUMERIC(10,2) NOT NULL,currency VARCHAR(3) NOT NULL,transaction_id VARCHAR(190),payload JSONB,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(provider,transaction_id));
CREATE TABLE IF NOT EXISTS coupon_usages (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,coupon_id BIGINT NOT NULL REFERENCES coupons(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(order_id));
CREATE TABLE IF NOT EXISTS quizzes (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,course_id BIGINT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,lesson_id BIGINT REFERENCES lessons(id) ON DELETE SET NULL,title VARCHAR(190) NOT NULL,description TEXT,passing_score SMALLINT NOT NULL DEFAULT 70,time_limit_minutes SMALLINT,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS quiz_questions (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,quiz_id BIGINT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,type VARCHAR(30) NOT NULL,question TEXT NOT NULL,points SMALLINT NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS quiz_answers (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,question_id BIGINT NOT NULL REFERENCES quiz_questions(id) ON DELETE CASCADE,text TEXT NOT NULL,is_correct BOOLEAN NOT NULL DEFAULT FALSE,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS quiz_attempts (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,quiz_id BIGINT NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,score NUMERIC(5,2) NOT NULL,points_earned INT NOT NULL,points_total INT NOT NULL,passed BOOLEAN NOT NULL,answers JSONB,submitted_at TIMESTAMP NOT NULL DEFAULT NOW(),created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS certificates (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,course_id BIGINT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,code VARCHAR(100) UNIQUE,issued_at TIMESTAMP NOT NULL DEFAULT NOW(),created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(course_id,user_id));
CREATE TABLE IF NOT EXISTS reviews (id BIGSERIAL PRIMARY KEY,academy_id BIGINT NOT NULL REFERENCES academies(id) ON DELETE CASCADE,course_id BIGINT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,rating SMALLINT NOT NULL,comment TEXT,status VARCHAR(20) NOT NULL DEFAULT 'approved',created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(course_id,user_id));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,academy_id BIGINT REFERENCES academies(id) ON DELETE SET NULL,action VARCHAR(190) NOT NULL,entity VARCHAR(190),entity_id BIGINT,ip VARCHAR(45),user_agent TEXT,created_at TIMESTAMP NOT NULL DEFAULT NOW());
